ROOT=pathlib.Path(__file__).resolve().parents[5];BASE=ROOT/'content/ap/written-drafts/2024';OUT=BASE/'reviewer-autumn'
def sha(p):return hashlib.sha256((ROOT/p).read_bytes()).hexdigest()
